/**
 * Standalone UK-only Khanda I Section II 2–22½ intermediate-number oracle.
 * Book: V Subrahmanya Sastri (1939) Uttara Kalamrita, PDF pp 7–13.
 * The seven Saptavargaja TOTALS below are PRINTED UK II page 10,
 * not generated by the SMV Astro engine or by BPHS.
 * No 2024 academic research data. No Ayurdaya computation.
 */
import assert from 'node:assert/strict';
import {uttaraKalamritaRectifiedTotal as bookTotal} from '../public/horoscope/offline/uttara-kalamrita-shadbala.browser.mjs';
import {
 UTTARA_KALAMRITA_NAISARGIKA_VIRUPA as natural,
 UTTARA_KALAMRITA_RELATION_VIRUPA as rel,
 uttaraKalamritaSaptavargajaFromRupa as varga,
 uttaraKalamritaSevenVargaSigns as signs,
 uttaraKalamritaSthana as sthana,
 uttaraKalamritaDigBala as dig,
 uttaraKalamritaNatonnatha as nat,
 uttaraKalamritaAyanaFromDeclination as ayana,
 uttaraKalamritaAspectVirupa as aspect,
 uttaraKalamritaDrigBala as drig,
 uttaraKalamritaKala as kala,
 uttaraKalamritaCheshta as cheshta,
 uttaraKalamritaSixBala as six
} from '../public/horoscope/offline/uttara-kalamrita-six-bala.browser.mjs';
let assertions=0;
const yes=(v,m)=>{assert.ok(v,m);assertions++};
const eq=(a,b,m)=>{assert.deepEqual(a,b,m);assertions++};
const close=(a,b,m,tol=1e-10)=>{yes(Number.isFinite(a)&&Math.abs(a-b)<=tol,
 m+' actual='+a+' expected='+b)};
const pNames=['சூரியன்','சந்திரன்','செவ்வாய்','புதன்','குரு','சுக்கிரன்','சனி'];

// UK printed p.12–13 Section II slokas 19½–21½: seven external COMPLETE
// book worked-example totals, independently printed Rupas.
// This certifies the book's aggregation formula for PUBLISHED EXAMPLE
// INPUTS only; it says nothing about date-specific natal input positions.

// UK Sastri II.16½–17½ COMMENTARY: independent worked declinations,
// south negative/north positive; same commentary prints rounded Rupas.
// Keep incompatible printed Sun/Moon figures as explicit discrepancies.
const obliquity=23+27/60;
const ayanaSamples=[
 {name:'செவ்வாய்',decl:10+10/60,bookRupa:.7},
 {name:'புதன்',decl:-(20+46/60),bookRupa:.921},
 {name:'குரு',decl:4+26/60,bookRupa:.58},
 {name:'சுக்கிரன்',decl:-(12+34/60),bookRupa:.23},
 {name:'சூரியன்',decl:-(22+20/60),bookRupa:.04125},
 {name:'சந்திரன்',decl:-(5+28/60),bookRupa:.65}
];
const ayanaBookExampleDiscrepancies=[];
for(const row of ayanaSamples){
 const result=ayana(row.name,row.decl);
 const signed=row.name==='புதன்'?Math.abs(row.decl):
  ['சந்திரன்','சனி'].includes(row.name)?-row.decl:row.decl;
 const directIndependent=(obliquity+signed)*1.25;
 close(result.rawVirupa,directIndependent,
   'UK commentary independent signed declination arithmetic '+row.name);
 const diffRupa=result.virupa/60-row.bookRupa;
 ayanaBookExampleDiscrepancies.push({graha:row.name,declination:row.decl,
  printedRupa:row.bookRupa,formulaRupa:result.virupa/60,
  differenceRupa:diffRupa});
 if(['சூரியன்','சந்திரன்'].includes(row.name))
  yes(Math.abs(diffRupa)>.01,
   'UK book printed Sun/Moon table is materially inconsistent with its own commentary '+row.name);
 else yes(Math.abs(diffRupa)<.005,
   'UK published Mars/Mercury/Jupiter/Venus table near rounded calculation '+row.name);
}
close(ayana('சூரியன்',0).virupa,obliquity*1.25,'UK equinox does NOT import BPHS 30');
close(ayana('சனி',-obliquity).virupa,obliquity*2*1.25,
  'UK Saturn southern solstice favoured');
close(ayana('புதன்',-obliquity).virupa,ayana('புதன்',obliquity).virupa,
  'UK Mercury always adds the declination magnitude');
eq(ayana('குரு',null).virupa,null,
 'UK missing equatorial input stays null (not fabricated)');
assert.throws(()=>ayana('குரு',91),RangeError);assertions++;
const bookFour=[3.83825,5.564,5.3799,7.658,5.1384,4.47685,4.97275];
const bookNatural=[1,.857,.286,.428,.571,.714,.143];
const bookDrig=[.2236,-.333,-.105,-.0256,.066,-.0123,.25];
const publishedShadbalaRupa=[5.06185,6.088,5.5609,8.0604,5.7754,5.17855,5.36575];
for(let i=0;i<7;i++)
 close(bookTotal(bookFour[i],bookNatural[i],bookDrig[i]),
   publishedShadbalaRupa[i],pNames[i]+' UK 7 final printed worked-example totals');

// Faithful row-by-row transcription from UK Section II printed table (p.9).
// DO NOT reconstruct values to force a printed TOTAL. Values written with
// 3 decimals are TRUNCATED; Jupiter Drekkana ".157" has a materially
// inconsistent 0.032 Rupa contribution, far greater than rounding.
// The book's printed 7 total line is retained independently.
const bookPrintedRows=[
 [0.375,.125,.187,.187,.125,.187,.375],
 [.25,.125,.125,.125,.125,.125,.375],
 [.375,.187,.375,.375,.375,.062,.187],
 [.25,.187,.375,.062,.062,.375,.062],
 [.75,.187,.157,.375,.187,.375,.187],
 [.25,.187,.187,.125,.187,.125,.375],
 [.125,.125,.375,.125,.375,.375,.125]
];
const expectedTotals=[1.5625,1.25,1.9375,1.375,2.25,1.4375,1.625];
const independentPrintedDeltas=[];
for(let n=0;n<7;n++){
 const row=bookPrintedRows[n],printedSum=row.reduce((a,b)=>a+b,0);
 const printedBookTotal=expectedTotals[n];
 const delta=printedBookTotal-printedSum;
 independentPrintedDeltas.push({graha:pNames[n],printedRowSum:printedSum,
   printedTotal:printedBookTotal,discrepancyRupa:delta});
 if(n===4){
  close(delta,.032,'Jupiter: printed Drekhana .157 is NOT fixed by usual truncation',1e-10);
  yes(Math.abs(delta)>.01,'Jupiter book row inconsistency flagged, never forged');
 }else
  yes(Math.abs(delta)<=.003,'other UK book row matches expected within truncation '+pNames[n]);
 const rowRecomputedByModule=varga([row[0],...row.slice(1).map(x=>x*2)]);
 close(rowRecomputedByModule.totalVirupa,printedSum*60,
   'UK literal row arithmetic independently matches '+pNames[n]);
}
eq(Object.values(rel),[60,45,30,22.5,15,7.5,3.75,1.875],
 'UK full Rupa dignity ladder is NOT prior BPHS 20/10/4/2');
for(const [i,name] of pNames.entries()){
 const rank=[7,6,2,3,4,5,1][i];
 close(natural[name],rank*60/7,name+' exact UK 1/7 natural sequence');
}
eq(signs(15).signs[2],11,'UK AUTHOR preferred second Drekkana Aries = Pisces (12th)');
eq(signs(25).signs[2],10,'UK AUTHOR preferred third Drekkana Aries = Aquarius (11th)');
eq(signs(1).signs[2],0,'UK first Drekkana same sign');
eq(signs(30+1).signs[1],3,'Taurus first Hora Moon');
eq(signs(1).signs[1],4,'Aries first Hora Sun');
eq(signs(30+18).trimsamsaLord,'குரு','even sign Trimsamsa Jupiter 3rd portion');
for(const [name,expected] of [
 ['சூரியன்',60],['சந்திரன்',0],['செவ்வாய்',0],
 ['புதன்',60],['குரு',60],['சுக்கிரன்',60],['சனி',0]
])close(nat(name,12).virupa,expected,'UK Natonnata at local apparent noon '+name);
close(nat('புதன்',0).virupa,0,'UK Mercury Unnata at midnight NOT flat 60');
close(nat('சனி',0).virupa,60,'UK Saturn Nata at midnight');
const signPositions=Object.fromEntries(pNames.map((p,i)=>[p,[4,3,0,2,8,1,9][i]]));
const sunExalt=sthana({planet:'சூரியன்',longitude:10,bhava:1,signPositions});
close(sunExalt.grades[0].virupa,60,'UK Sun exalted Rasi 1 full Rupa');
close(sunExalt.kendradi,60,'UK Kendra 1 Rupa');
const sunRetroExalt=sthana({planet:'சூரியன்',longitude:10,bhava:1,signPositions,retrograde:true});
close(sunRetroExalt.grades[0].virupa,0,'UK II.6 reverse exaltation retrograde rule diagnostic');
const sunRetroDeb=sthana({planet:'சூரியன்',longitude:190,bhava:8,signPositions,retrograde:true});
close(sunRetroDeb.grades[0].virupa,60,'UK II.6 retrograde debilitation -> full strength');
const bhavas=Array.from({length:12},(_,i)=>({house:i+1,longitude:i*30,madhyaLongitude:i*30}));
close(dig({planet:'சூரியன்',longitude:270,bhavas}).virupa,60,
 'UK Sun ideal southern tenth-house position');
close(dig({planet:'சூரியன்',longitude:90,bhavas}).virupa,0,
 'UK Sun opposite fourth directional zero');
for(const [p,a,expected] of [
 ['சூரியன்',180,60],['சனி',60,60],['சனி',270,60],
 ['குரு',120,60],['குரு',240,60],
 ['செவ்வாய்',90,60],['செவ்வாய்',210,60],
 ['சூரியன்',60,15],['சூரியன்',90,45],
 ['சூரியன்',120,30],['சூரியன்',150,0],['சூரியன்',30,0],
 ['சூரியன்',300,0]
])close(aspect(a,p),expected,'UK II Drig exact angular breakpoint '+p+' '+a);
const chart=pNames.map((name,i)=>({
 name,longitude:[0,60,180,240,30,330,270][i],
 bhava:[1,3,7,9,2,12,10][i],eclipticLatitude:i*0.1,
 strength:{retrograde:false}
}));
const drigSun=drig('சூரியன்',chart);
close(drigSun.virupa,drigSun.entries.reduce((a,b)=>a+b.signedVirupa,0),
 'UK Drig full aspect signs algebraic sum independent');
eq(drigSun.entries.length,6,'UK all six other visible planets counted');
const sunnyKala=kala({planet:'சூரியன்',apparentSolarHour:12,
 solarLongitude:0,moonLongitude:180,planets:chart,
 owners:{abda:'சூரியன்',masa:'சூரியன்',vara:'சூரியன்',hora:'சூரியன்'},
 tribhagaLord:'சூரியன்',declinationVirupa:50});
close(sunnyKala.parts.abda,15,'UK year lord 1/4 Rupa');
close(sunnyKala.parts.masa,30,'UK month lord 1/2 Rupa');
close(sunnyKala.parts.vara,45,'UK weekday lord 3/4 Rupa');
close(sunnyKala.parts.hora,60,'UK Hora lord 1 Rupa');
close(sunnyKala.totalVirupa,Object.values(sunnyKala.parts).reduce((a,b)=>a+b,0),
 'UK Kala subtotal independent complete sum');
eq(sunnyKala.warSeparateVirupa,0,'UK war kept OUTSIDE Kala');
const lacking=cheshta();
eq(lacking.virupa,null,'NO historical triple -> no fabricated Cheshta');
eq(lacking.certified,false,'No orbital source -> no certificate');
close(cheshta({meanLongitude:10,trueLongitude:10,sheeghrocca:190,
 sourceFrameVerified:true}).virupa,60,'UK true/mean/sighra full 180° Kendra');
eq(cheshta({meanLongitude:10,trueLongitude:10,sheeghrocca:190}).certified,false,
 'non-certified source data fail closed');
const computed=six({planets:chart,bhavas,apparentSolarHour:12,
 owners:{abda:'சூரியன்',masa:'சந்திரன்',vara:'செவ்வாய்',hora:'புதன்'},
 tribhagaLord:'சூரியன்',
 declinations:Object.fromEntries(pNames.map(p=>[p,30]))});
eq(computed.basis,'Uttara Kalamrita only','exact book basis on new path');
eq(computed.ayurdayaCalculationIncluded,false,'future Section III excluded completely');
eq(computed.completeCertification,false,'UK entire certification not faked');
for(const name of pNames){
 const row=computed.birthSevenGraha[name];
 eq(row.cheshta.virupa,null,'seven grahas do not receive speed-bin estimates '+name);
 eq(row.totalVirupa,null,'no spurious whole Shadbala '+name);
 eq(row.classicalCertified,false,'no self-certified UK Shadbala '+name);
 yes(row.sthana.saptavargajaPartsVirupa.length===7,
  'all seven UK varga intermediate terms '+name);
 yes(row.drig.entries.length===6,'UK six drig aspect intermediates '+name);
}
assert.throws(()=>varga([1,1]),RangeError);assertions++;
assert.throws(()=>signs(NaN),TypeError);assertions++;
assert.throws(()=>aspect(NaN,'குரு'),TypeError);assertions++;
assert.throws(()=>sthana({planet:'ராகு',longitude:0,bhava:1,signPositions}),RangeError);assertions++;
console.log(JSON.stringify({pass:true,assertions,
 ukSaptavargajaPrintedSevenTotalsReconciled:6,
 ukJupiterDrekkanaPrintedSourceInconsistency:true,
 ukAyanaIndependentBookExamples:ayanaBookExampleDiscrepancies,
 ukAyanaCommentaryFormulaVerified:true,
 ukAyanaPrintedSunMoonMismatch:true,
 ukLiteralPrintedRowDiscrepancies:independentPrintedDeltas,
 ukShadbalaPrintedSevenFinalTotalsReconciled:7,
 ukDrekkanaAuthorSpecificVerified:true,
 ukNaturalSevenVerified:true,
 ukSixBalaIntermediateCategories:6,
 grahasWithUKIntermediates:7,
 unverifiedHistoricalOrbitalInputs:7,
 allIntermediateAstronomicalSourcesCertified:false,
 completeSevenGrahaUttaraKalamritaShadbalaCertified:false,
 ayurdayaAdded:false
}));
